import logging
import os
import os.path
import select
import socket
import traceback
from random import randint
from threading import currentThread, RLock, Lock

import ta_ue_plugin_android.uepc.adb_proxy as adb
from ta_ue_plugin_android.uepc.cons_usb import UsbCons
from ta_ue_plugin_android.uepc.ue_manager_exceptions import UeNotFoundException
from ta_ue_plugin_android.uepc.ue_pc_logger import LoggerAdapter4EmptyExtra


class SocketControl(UsbCons):
    """SocketControl"""
    # pylint: disable=too-many-instance-attributes

    def __init__(self, ue_sn):
        """
        :param ue_sn:
        :param logger:
        """
        raw_logger = logging.getLogger("ute_ue.uepc")
        self.logger = LoggerAdapter4EmptyExtra(raw_logger, {'area': 'USB', 'ue_id': ue_sn})
        # TODO: display ue_id in logs
        self.host = '127.0.0.1'
        self.ue_sn = ue_sn
        self.sock = socket.socket()
        self.send_lock = Lock()
        self.recv_lock = Lock()
        self.port = -1
        self.isConnected = False
        # if none, use self.sock.recv(1)
        # @type recv_data_buffer_or_none: List(Bytes)
        self.recv_data_buffer_or_none = None
        self.recv_data_buffer_lock = RLock()

    def connect(self):
        """
        :param func:
        :return:
        """
        try:
            self.logger.info("Start connect socket to UE: " + str(self.ue_sn))
            self.logger.debug("connect, before adb_forward_list")
            forwards = adb.adb_forward_list(self.ue_sn)
            self.logger.debug("connect, after adb_forward_list: " + str(forwards))
            if forwards:
                self.port = forwards[0]
            else:
                self.port = self._find_free_tcp_port()
                self._forward_or_raise()
            if self.port == -1:
                raise Exception('self.port == -1')
            args = (self.host, self.port)
            self.logger.debug('connecting to socket (%s, %d)' % args)
            self.sock = socket.socket()
            self.sock.settimeout(10)
            self.sock.connect(args)
            # ustaw timeout na send/receive na 0.4 sekundy
            self.sock.settimeout(0.4)
            self.logger.info('connect success from thread ' + str(currentThread()))
            self.isConnected = True
        except UeNotFoundException as e:
            raise e
        except Exception as e:
            trace = traceback.format_exc()
            self.logger.info('fail connect to socket, exception = {} - {}, trace = \n{}'.format(type(e), e, trace))
            self.isConnected = False
            self.logger.error(e, exc_info=True)
            raise e

    def _forward_or_raise(self):
        self.logger.debug("perform port forwarding for ue %s on port %d" % (self.ue_sn, self.port))
        if not adb.adb_forward_port(self.ue_sn, self.port):
            raise UeNotFoundException("UE with sn: %s is not connected" % (self.ue_sn))
        self.logger.debug("success port forwarding for ue %s on port %d" % (self.ue_sn, self.port))

    def connected(self):
        """Check connection state."""
        return self.isConnected

    def close(self):
        """
        :param func:
        :return:
        """
        try:
            self.isConnected = False
            self.sock.shutdown(socket.SHUT_RDWR)
            self.sock.close()
        except Exception as e:
            raise e
            # TODO: better exception handling

    ###########################################################

    def _find_free_tcp_port(self):
        """
        Finds free tcp port on this machine.
        :param func:
        :return:
        """
        try:
            while True:
                randport = randint(60123, 61999)
                self.logger.debug('Random port for Android application = ' + str(randport))
                proc = os.popen('netstat -ano | grep ' + str(randport))
                netstat = proc.read()
                proc.close()
                self.logger.debug('Netstat output = ' + netstat)
                if netstat == '':
                    return randport
        except Exception:
            raise

    ###########################################################

    def read_packet_from_buffer(self):
        """
        Reads one packet from private buffer.
        Return False, False if no packet in private buffer.
        Return id:byte, body:string if some msg is in private buffer
        :return: Tuple(byte, string) or Tuplbe(False, False)
        """
        with self.recv_data_buffer_lock:
            if self.recv_data_buffer_or_none is None or not self.recv_data_buffer_or_none:
                return False, False
            bytes_goes = 0
            state = 0
            # state = 0 - wait for STX
            # state = 1 - read packet id
            # state = 2 - read packet body
            # state = 3 - got ETX
            msg_id = False
            body = ''
            for received_bytes in self.recv_data_buffer_or_none:
                byte_goes = 0
                for byte in received_bytes:
                    if state == 3:
                        break
                    body, msg_id, state = self._process_reading_byte(body, byte, msg_id, state)
                    byte_goes += 1
                else:
                    bytes_goes += 1
                    continue  # executed if the loop ended normally (no break)
                break  # executed if 'continue' was skipped (break in inner loop)
            return self._pop_if_need_data_from_buffer(body, byte_goes, bytes_goes, msg_id, state)

    def _pop_if_need_data_from_buffer(self, body, byte_goes, bytes_goes, msg_id, state):
        if state != 3:
            return False, False
        self._pop_readed_bytes(byte_goes, bytes_goes)
        return msg_id, body

    def _pop_readed_bytes(self, byte_goes, bytes_goes):
        del self.recv_data_buffer_or_none[1:bytes_goes]
        self.recv_data_buffer_or_none[0] = self.recv_data_buffer_or_none[0][byte_goes:]
        if not self.recv_data_buffer_or_none[0]:
            self.recv_data_buffer_or_none.pop(0)

    def _process_reading_byte(self, body, byte, msg_id, state):
        if state == 2:
            if byte == self.ETX:
                state = 3
            else:
                body += byte
        if state == 1:
            msg_id = byte
            state = 2
        if state == 0 and byte == self.STX:
            state = 1
        return body, msg_id, state

    def io_step_with_select_select(self, to_send_lambda, after_send_lambda_or_none=None):
        """
        Doing select.select to receive data to private buffer & send data returning by lambda expression: to_send_lambda.

        :param to_send_lambda: Bytes lambda(void)
        :param after_send_lambda_or_none: void lambda(void)
        :return:
        """
        self._ensure_lambdas(after_send_lambda_or_none, to_send_lambda)
        conn = self.sock
        try:
            ready_to_read, ready_to_write, _ = select.select([conn, ], [conn, ], [], 5)
        except select.error as e:
            self.logger.warning("Got select.select exception " + str(e) + ", I am closing")
            self.logger.warning(e, )
            self.close()
            raise e
        if ready_to_read:
            recv = (conn.recv(2048)).decode("utf-8", errors='ignore')
            # do stuff with received data
            self._data_rev_from_select(recv)
        if ready_to_write:
            # connection established, send some stuff
            to_send = to_send_lambda()
            conn.send(to_send.encode("utf-8", errors='ignore'))
            if after_send_lambda_or_none is not None:
                after_send_lambda_or_none()
        return True

    def _ensure_lambdas(self, after_send_lambda_or_none, to_send_lambda):
        if not callable(to_send_lambda):
            self.logger.error("Excpected lambda expression in SocketControlListener::io_step_with_select_select"
                              "param {}, given: {}".format(to_send_lambda, str(to_send_lambda)))
            raise RuntimeError('wanted lambda on param after_send_lambda_or_none')
        if after_send_lambda_or_none and not callable(after_send_lambda_or_none):
            self.logger.error("Excpected lambda expression in SocketControlListener::io_step_with_select_select"
                              "param {}, given: {}".format(after_send_lambda_or_none, str(after_send_lambda_or_none)))
            raise RuntimeError('wanted lambda on param after_send_lambda_or_none')

    def _data_rev_from_select(self, recv):
        with self.recv_data_buffer_lock:
            if self.recv_data_buffer_or_none is None:
                self.recv_data_buffer_or_none = [recv]
            else:
                self.recv_data_buffer_or_none.append(recv)


if __name__ == "__main__":
    sock = SocketControl(12345)
    sock.connect()
